const axios = require('axios');
const token = process.env.PARAGON_USER_TOKEN;
const projectId = process.env.PARAGON_PROJECT_ID;

async function probe() {
  const urls = [
    `https://actionkit.useparagon.com/actions`,
    `https://api.useparagon.com/actions`,
    `https://api.useparagon.com/projects/${projectId}/actions`,
    `https://actionkit.useparagon.com/api/v1/actions`,
    `https://actionkit.useparagon.com/projects/${projectId}/actions`
  ];

  for (const url of urls) {
    try {
      console.log(`Trying ${url}`);
      const res = await axios.get(url, {
        headers: { Authorization: `Bearer ${token}` }
      });
      console.log(`Success on ${url}`, res.data);
      return;
    } catch (e) {
      console.log(`Failed on ${url}: ${e.response ? e.response.status : e.message}`);
    }
  }
}
probe();
EOF
