const fs = require('fs');
const axios = require('axios');

async function main() {
  try {
    const trialId = fs.readFileSync('/logs/artifacts/trial_id', 'utf8').trim();
    const token = process.env.PARAGON_USER_TOKEN;
    const projectId = process.env.PARAGON_PROJECT_ID;

    if (!token || !projectId) {
      console.error('Missing PARAGON_USER_TOKEN or PARAGON_PROJECT_ID');
      return;
    }

    const toolsUrl = `https://actionkit.useparagon.com/projects/${projectId}/tools`;

    // Fetch available tools
    const getRes = await axios.get(toolsUrl, {
      headers: { Authorization: `Bearer ${token}` }
    });

    const tools = getRes.data.tools || {};

    if (tools['SLACK_SEND_MESSAGE']) {
      // Execute the action
      await axios.post(toolsUrl, {
        tool: "SLACK_SEND_MESSAGE",
        parameters: {
          channel: "#general",
          message: `Hello from Paragon! trial_id: ${trialId}`
        }
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fs.writeFileSync('/home/user/paragon-task/output.log', 'Message sent\n');
    } else {
      fs.writeFileSync('/home/user/paragon-task/output.log', 'Action not available\n');
    }
  } catch (error) {
    console.error('Error:', error.response ? error.response.data : error.message);
    // In case of error, we can also log it if needed, but requirements say log outcome
  }
}

main();
EOF
